/** 直接给详情页组件的 form 赋值（弹窗选择类字段用），并触发对应字段重新校验 */
async function setFormValues(page, patch) {
  await page.evaluate(async (p) => {
    const app = document.querySelector('#app').__vue__
    const walk = (c, d = 0) => {
      if (!c || d > 12) return null
      const f = c.form || (c.$data && c.$data.form)
      if (f && typeof f === 'object' && typeof c.submitForm === 'function') return c
      for (const ch of c.$children || []) {
        const r = walk(ch, d + 1)
        if (r) return r
      }
      return null
    }
    const vm = walk(app)
    if (!vm) throw new Error('未找到详情表单组件')
    Object.keys(p).forEach((k) => vm.$set(vm.form, k, p[k]))
    await vm.$nextTick()
    // 表单模型是直接改的，v-model 的 change 事件没走，这里主动清掉已有校验提示
    const form = vm.$refs.form
    if (form && typeof form.clearValidate === 'function') {
      await new Promise((r) => form.clearValidate(() => r()))
    }
  }, patch)
}

