import { test } from '@playwright/test'
import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'

test('probe detail vm via container', async ({ page }) => {
  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find(
    (r) => r.filePath === 'supervision/account/regulatoryAccountNew/index' && !String(r.path).includes(':tableid')
  )
  await gotoHashPath(page, listRoute.path)
  await waitForPageLoading(page)
  await page.locator('button:has-text("新增")').first().click()
  await page.waitForURL(/formMode=add/, { timeout: 20000 })
  await page.locator('button:has-text("保存")').first().waitFor({ state: 'visible', timeout: 20000 })

  const info = await page.evaluate(() => {
    const el = document.querySelector('.detail-container')
    let node = el
    const chain = []
    let found = null
    while (node && chain.length < 20) {
      if (node.__vue__) {
        const vm = node.__vue__
        chain.push({
          tag: node.tagName,
          cls: String(node.className).slice(0, 50),
          hasForm: !!vm.form,
          hasSubmit: typeof vm.submitForm === 'function',
          businessName: vm.businessName
        })
        if (vm.form && typeof vm.submitForm === 'function' && !found) {
          found = { businessName: vm.businessName, formKeys: Object.keys(vm.form), refs: Object.keys(vm.$refs || {}) }
        }
      }
      node = node.parentElement
    }
    return { chain, found }
  })
  console.log('PROBE=' + JSON.stringify(info, null, 1))
})

