function saveButton(page) {
  return page.locator('button:has-text("保存")').first()
}

/**
 * 弹窗选择类字段：点开 readonly 输入框触发的选择弹窗，勾第一行后确定。
 * @param {import('@playwright/test').Page} page
 * @param {string} placeholder 触发弹窗的输入框 placeholder，如「点击选择监管机构」
 * @param {string} fieldLabel 用于失败提示的字段名
 */
async function pickFromDialog(page, placeholder, fieldLabel) {
  await page.locator(`input[placeholder="${placeholder}"]`).first().click()

  const dialog = page.locator('.el-dialog').filter({ has: page.locator('.el-table') }).last()
  await expect(dialog, `字段「${fieldLabel}」的选择弹窗未打开`).toBeVisible({ timeout: 15000 })

  // 等弹窗表格出数据行（首行有内容，不是「暂无数据」）
  const firstRow = dialog.locator('.el-table__body tbody tr').first()
  await expect(firstRow, `字段「${fieldLabel}」的弹窗无数据`).toBeVisible({ timeout: 20000 })
  const rowText = (await firstRow.innerText()).trim()
  expect(rowText, `字段「${fieldLabel}」的弹窗表格为空`).not.toContain('暂无数据')

  // 单选表格：勾首行复选框
  await firstRow.locator('.el-checkbox__inner, .el-radio__inner').first().click()
  await dialog.locator('button:has-text("确定")').click()
  await expect(dialog, `字段「${fieldLabel}」的弹窗未关闭`).toBeHidden({ timeout: 15000 })
}

