/**
 * 直接给详情页组件的 form 赋值（弹窗选择类字段用），并重跑校验。
 * 组件实例从 `.detail-container` 的 __vue__ 取，避免在整棵树里误命中其它带 form 的组件。
 */
async function setFormValues(page, patch) {
  const result = await page.evaluate((p) => {
    const vm = document.querySelector('.detail-container').__vue__
    if (!vm || !vm.form) throw new Error('未找到详情表单组件')
    Object.keys(p).forEach((k) => vm.$set(vm.form, k, p[k]))
    // 直接改模型不会触发 v-model 的 change，主动清掉已有的必填提示
    const formRef = vm.$refs.form
    if (formRef && typeof formRef.clearValidate === 'function') formRef.clearValidate()
    return { businessName: vm.businessName, applied: Object.keys(p) }
  }, patch)
  expect(result.businessName, '详情组件业务名不符').toBeTruthy()
  return result
}

