    page
  }) => {
    await openAddPage(page, 'supervision/account/superviseAgreementNew/index')

    // 协议版本下拉依赖版本接口，确认有可选版本（不能是「无数据」）
    await pickSelectOption(page, page.locator('.detail-container'), '协议版本', '')

    // 项目名称弹窗必须能拉到项目
    await pickFromDialog(page, '点击选择项目名称', '项目名称')
    await expect(
      page.locator('input[placeholder="点击选择项目名称"]'),
      '选完项目后项目名称未回填'
    ).not.toHaveValue('', { timeout: 15000 })

    // 监管账号弹窗按 projectId + openaccountTag=1 过滤，本环境库中无已开户账户，
    // 这里只断言弹窗能正常打开（有表格），不伪造数据去绕过业务校验。
    await page.locator('input[placeholder="点击选择监管账号"]').first().click()
    const accountDialog = page.locator('.el-dialog').filter({ has: page.locator('.el-table') }).last()
    await expect(accountDialog, '监管账号选择弹窗未打开').toBeVisible({ timeout: 15000 })
    await expect(accountDialog.locator('.el-table'), '监管账号弹窗无表格').toBeVisible({ timeout: 15000 })
